questionvariables.text:
stack_include_contrib("prooflib.mac");

/* 1. Déclaration des blocs */
proof_steps: [
    /* Les bonnes étapes dans l'ordre */
    ["L1", "L'air pénètre par les fosses nasales où il est filtré, réchauffé et humidifié."],
    ["L2", "Il passe par le pharynx, puis descend dans la trachée."],
    ["L3", "La trachée se divise en deux bronches principales qui pénètrent dans les poumons."],
    ["L4", "Les bronches se ramifications en bronchioles, aboutissant aux alvéoles pulmonaires."],
    ["L5", "Le dioxygène (O2) diffuse de l'alvéole vers le sang des capillaires sanguins."],
    ["L6", "Le dioxyde de carbone (CO2) diffuse du sang vers la cavité de l'alvéole pour être expiré."],

    /* Les distracteurs (erreurs classiques de lycéens) */
    ["D1", "Le dioxygène passe directement des fosses nasales aux bronches sans passer par la trachée."],
    ["D2", "Le dioxyde de carbone (CO2) est absorbé par les alvéoles pour être stocké dans les poumons."],
    ["D3", "L'air arrive dans l'œsophage avant de rejoindre les poumons."]
];

/* 2. Structure de la bonne réponse */
ta: proof("L1", "L2", "L3", "L4", "L5", "L6");

/* 3. Mélange aléatoire */
proof_steps: random_permutation(proof_steps);

/* 4. Préparation de l'évaluation */
tal: proof_alternatives(ta);
tas: setify(map(proof_flatten, tal));
